import Foundation
struct GameMode: Decodable {
    let id: Int
    let isCooperative: Bool
    enum CodingKeys: String, CodingKey {
        case id
        case isCooperative = "is_cooperative"
    }
}
let data = Data(#"{"id":5,"is_cooperative":true}"#.utf8)
do {
    let mode = try JSONDecoder().decode(GameMode.self, from: data)
    print(mode.isCooperative)
} catch { print("Некорректные данные") }

is_cooperative связан с isCooperative и читается как Bool. Вывод true; строковый "true" нарушил бы тип.

